CREATE FUNCTION check_learning_completion_provenance() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE participant hr_learning_record%ROWTYPE;session_record hr_learning_record%ROWTYPE;programme hr_learning_record%ROWTYPE;request_record hr_learning_record%ROWTYPE;planned numeric;attended numeric;passes boolean;completed date;expires date;assessor text;
BEGIN
 IF NEW.kind<>'completion' OR NEW.state NOT IN('issued','failed') THEN RETURN NULL;END IF;
 SELECT * INTO participant FROM hr_learning_record WHERE tenant_id=NEW.tenant_id AND id=NEW.parent_id AND kind='participation';
 SELECT * INTO session_record FROM hr_learning_record WHERE tenant_id=NEW.tenant_id AND id=participant.parent_id AND kind='session';
 SELECT * INTO programme FROM hr_learning_record WHERE tenant_id=NEW.tenant_id AND id=NEW.programme_id AND kind='programme';
 SELECT * INTO request_record FROM hr_learning_record WHERE tenant_id=NEW.tenant_id AND id=participant.terms->>'request_id' AND kind='request';
 IF participant.state IS DISTINCT FROM 'completed' OR request_record.state IS DISTINCT FROM 'fulfilled' OR session_record.state NOT IN('scheduled','closed') OR participant.employee_id IS DISTINCT FROM NEW.employee_id OR request_record.employee_id IS DISTINCT FROM NEW.employee_id OR participant.programme_id IS DISTINCT FROM NEW.programme_id OR request_record.programme_id IS DISTINCT FROM NEW.programme_id THEN RAISE EXCEPTION 'Certified learning requires completed participation and fulfilled approved-request provenance';END IF;
 IF jsonb_array_length(participant.terms->'attendance')<>jsonb_array_length(session_record.terms->'slots') OR EXISTS(SELECT 1 FROM jsonb_array_elements(session_record.terms->'slots')slot WHERE(slot->>'ends_at')::timestamptz>clock_timestamp() OR(SELECT count(*) FROM jsonb_array_elements(participant.terms->'attendance')a WHERE(a->>'starts_at')::timestamptz=(slot->>'starts_at')::timestamptz)<>1) THEN RAISE EXCEPTION 'Every finished lesson requires one attendance entry';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(participant.terms->'attendance')a LEFT JOIN LATERAL(SELECT slot FROM jsonb_array_elements(session_record.terms->'slots')slot WHERE(slot->>'starts_at')::timestamptz=(a->>'starts_at')::timestamptz) s ON true WHERE s.slot IS NULL OR(a->>'minutes')::numeric<0 OR(a->>'minutes')::numeric>extract(epoch from((s.slot->>'ends_at')::timestamptz-(s.slot->>'starts_at')::timestamptz))/60) THEN RAISE EXCEPTION 'Attendance cannot exceed retained lesson duration';END IF;
 SELECT sum(extract(epoch from((s->>'ends_at')::timestamptz-(s->>'starts_at')::timestamptz))/60),max((s->>'ends_at')::timestamptz)::date INTO planned,completed FROM jsonb_array_elements(session_record.terms->'slots')s;
 SELECT sum((a->>'minutes')::numeric) INTO attended FROM jsonb_array_elements(participant.terms->'attendance')a;
 passes:=attended*100>=planned*(programme.terms->>'minimum_attendance_percent')::numeric AND(programme.terms->>'pass_mark' IS NULL OR(participant.terms->>'assessment_score')::numeric>=(programme.terms->>'pass_mark')::numeric);
 IF planned<(programme.terms->>'duration_minutes')::numeric OR NEW.terms->>'completed_on' IS DISTINCT FROM completed::text OR(NEW.terms->>'attendance_percent')::numeric IS DISTINCT FROM round(attended/planned*100,2) OR NEW.terms->>'assessment_score' IS DISTINCT FROM participant.terms->>'assessment_score' OR NEW.terms->>'evidence_reference' IS DISTINCT FROM participant.terms->>'evidence_reference' OR NEW.terms->>'result' IS DISTINCT FROM (CASE WHEN passes THEN 'passed' ELSE 'failed' END) OR NEW.state<>(CASE WHEN passes THEN 'issued' ELSE 'failed' END) OR(programme.terms->>'pass_mark' IS NOT NULL AND participant.terms->>'assessment_score' IS NULL) THEN RAISE EXCEPTION 'Learning result must match actual retained attendance, assessment and programme rules';END IF;
 expires:=CASE WHEN programme.terms->>'validity_months' IS NULL THEN NULL ELSE(completed+make_interval(months=>(programme.terms->>'validity_months')::int))::date END;
 IF NEW.terms->>'valid_until' IS DISTINCT FROM expires::text THEN RAISE EXCEPTION 'Certificate expiry must follow the published programme';END IF;
 SELECT actor_id INTO assessor FROM hr_learning_event WHERE tenant_id=NEW.tenant_id AND record_id=participant.id AND action='attendance' ORDER BY version DESC LIMIT 1;
 IF assessor IS NULL OR NEW.updated_by=assessor OR length(btrim(coalesce(NEW.terms->>'certificate_id','')))<12 THEN RAISE EXCEPTION 'Independent certification and retained assessment evidence are required';END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER learning_completion_provenance AFTER INSERT OR UPDATE ON hr_learning_record DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_learning_completion_provenance();
CREATE UNIQUE INDEX learning_certificate_identifier ON hr_learning_record(tenant_id,(terms->>'certificate_id')) WHERE kind='completion';
INSERT INTO nexora_schema_migration(module_name,version,name) VALUES('hr',122,'learning_completion_provenance');
